content.content:
1	/* Tour launch overlay — big, centered, red */
2	.tour-overlay {
3	  position: fixed;
4	  inset: 0;
5	  z-index: 2000;
6	  display: flex;
7	  align-items: center;
8	  justify-content: center;
9	  padding: 24px;
10	  background: rgba(15, 0, 0, .55);
11	  backdrop-filter: blur(6px);
12	  -webkit-backdrop-filter: blur(6px);
13	  animation: tour-fade-in .25s ease-out;
14	}
15	@keyframes tour-fade-in {
16	  from { opacity: 0; }
17	  to   { opacity: 1; }
18	}
19	.tour-card {
20	  position: relative;
21	  width: min(620px, 100%);
22	  max-height: calc(100vh - 48px);
23	  overflow: auto;
24	  text-align: center;
25	  padding: clamp(36px, 6vw, 64px) clamp(28px, 5vw, 56px);
26	  border-radius: 24px;
27	  background: linear-gradient(160deg, #c0252e 0%, #d63340 50%, #a51a22 100%);
28	  color: #fff;
29	  border: 2px solid rgba(255, 255, 255, .18);
30	  box-shadow: 0 30px 80px rgba(180, 20, 30, .45), 0 0 0 1px rgba(255,255,255,.08) inset;
31	  font-family: var(--font-body, inherit);
32	  animation: tour-pop-in .35s cubic-bezier(.16, 1, .3, 1);
33	}
34	@keyframes tour-pop-in {
35	  from { opacity: 0; transform: scale(.92) translateY(12px); }
36	  to   { opacity: 1; transform: scale(1)   translateY(0); }
37	}
38	.tour-close {
39	  position: absolute;
40	  top: 14px;
41	  right: 14px;
42	  width: 36px;
43	  height: 36px;
44	  border-radius: 50%;
45	  border: none;
46	  background: rgba(0, 0, 0, .25);
47	  color: #fff;
48	  font-size: 18px;
49	  display: inline-flex;
50	  align-items: center;
51	  justify-content: center;
52	  cursor: pointer;
53	  transition: background .15s, transform .15s;
54	}
55	.tour-close:hover { background: rgba(0, 0, 0, .45); transform: scale(1.05); }
56	.tour-icon {
57	  width: 76px;
58	  height: 76px;
59	  border-radius: 50%;
60	  background: rgba(255, 255, 255, .14);
61	  border: 2px solid rgba(255, 255, 255, .35);
62	  display: inline-flex;
63	  align-items: center;
64	  justify-content: center;
65	  font-size: 36px;
66	  margin-bottom: 22px;
67	  animation: tour-icon-pulse 2s ease-in-out infinite;
68	}
69	@keyframes tour-icon-pulse {
70	  0%, 100% { box-shadow: 0 0 0 0    rgba(255, 255, 255, .35); }
71	  50%      { box-shadow: 0 0 0 14px rgba(255, 255, 255, 0); }
72	}
73	.tour-eyebrow {
74	  font-family: var(--font-display, inherit);
75	  font-size: .76rem;
76	  font-weight: 700;
77	  letter-spacing: .2em;
78	  text-transform: uppercase;
79	  color: rgba(255, 255, 255, .82);
80	  margin-bottom: 12px;
81	}
82	.tour-title {
83	  font-family: var(--font-display, inherit);
84	  font-size: clamp(1.7rem, 4.4vw, 2.6rem);
85	  font-weight: 700;
86	  letter-spacing: -.025em;
87	  line-height: 1.1;
88	  margin: 0 0 16px;
89	  color: #fff;
90	  text-wrap: balance;
91	}
92	.tour-title em { font-style: italic; color: #ffd9b3; font-weight: 700; }
93	.tour-desc {
94	  font-size: 1.02rem;
95	  line-height: 1.6;
96	  color: rgba(255, 255, 255, .92);
97	  max-width: 46ch;
98	  margin: 0 auto 20px;
99	}
100	.tour-desc strong { color: #fff; font-weight: 700; }
101	.tour-countdown {
102	  display: inline-block;
103	  font-size: .9rem;
104	  color: rgba(255, 255, 255, .85);
105	  margin-bottom: 22px;
106	  padding: 6px 14px;
107	  border-radius: 999px;
108	  background: rgba(0, 0, 0, .2);
109	  border: 1px solid rgba(255, 255, 255, .15);
110	}
111	.tour-countdown strong { color: #fff; font-weight: 700; font-variant-numeric: tabular-nums; }
112	.tour-actions {
113	  display: flex;
114	  gap: 12px;
115	  flex-wrap: wrap;
116	  justify-content: center;
117	}
118	.tour-btn {
119	  font-family: var(--font-display, inherit);
120	  font-size: .95rem;
121	  font-weight: 600;
122	  padding: 13px 26px;
123	  border-radius: 999px;
124	  border: 2px solid transparent;
125	  cursor: pointer;
126	  display: inline-flex;
127	  align-items: center;
128	  gap: 8px;
129	  transition: background .15s, color .15s, border-color .15s, transform .1s;
130	}
131	.tour-btn:active { transform: scale(.97); }
132	.tour-btn-primary {
133	  background: #fff;
134	  color: #b01923;
135	}
136	.tour-btn-primary:hover { background: #ffe5e7; color: #8e1219; }
137	.tour-btn-ghost {
138	  background: transparent;
139	  color: #fff;
140	  border-color: rgba(255, 255, 255, .55);
141	}
142	.tour-btn-ghost:hover { background: rgba(0, 0, 0, .15); border-color: #fff; }
143	
144	@media (max-width: 520px) {
145	  .tour-overlay { padding: 12px; }
146	  .tour-card    { padding: 32px 24px; border-radius: 20px; }
147	  .tour-actions { flex-direction: column; align-items: stretch; }
148	  .tour-btn     { justify-content: center; }
149	}
150	@media (prefers-reduced-motion: reduce) {
151	  .tour-overlay, .tour-card, .tour-icon { animation: none; }
152	}
153	
154	/* TE — voice assistant floating button + panel */
155	.te-fab {
156	  position: fixed;
157	  z-index: 1998;
158	  right: 24px;
159	  top: 88px; /* below the fixed topnav */
160	  display: inline-flex;
161	  align-items: center;
162	  gap: 8px;
163	  padding: 8px 14px 8px 10px;
164	  border-radius: 999px;
165	  border: 1.5px solid var(--border-strong);
166	  background: var(--bg);
167	  color: var(--fg);
168	  font-family: var(--font-display);
169	  font-weight: 700;
170	  letter-spacing: .08em;
171	  font-size: .78rem;
172	  cursor: pointer;
173	  box-shadow: 0 10px 28px rgba(0,0,0,.12), 0 3px 8px rgba(0,0,0,.06);
174	  transition: border-color .15s, background .15s, color .15s, transform .1s;
175	}
176	.te-fab:hover { border-color: var(--brand); color: var(--brand); }
177	.te-fab:active { transform: scale(.97); }
178	.te-fab-label { letter-spacing: .14em; }
179	
180	.te-fab.te-status-awake  { border-color: var(--brand); color: var(--brand); }
181	.te-fab.te-status-listening { border-color: var(--brand); }
182	
183	.te-dot {
184	  width: 10px;
185	  height: 10px;
186	  border-radius: 50%;
187	  background: var(--fg-muted);
188	  flex: 0 0 auto;
189	  display: inline-block;
190	}
191	.te-dot-off    { background: var(--border-strong); }
192	.te-dot-listen { background: var(--brand); box-shadow: 0 0 0 0 rgba(214, 51, 132, .6); animation: te-pulse 1.6s infinite; }
193	.te-dot-awake  { background: var(--brand); box-shadow: 0 0 0 6px rgba(214, 51, 132, .2); }
194	@keyframes te-pulse {
195	  0%   { box-shadow: 0 0 0 0    rgba(214, 51, 132, .55); }
196	  70%  { box-shadow: 0 0 0 10px rgba(214, 51, 132, 0); }
197	  100% { box-shadow: 0 0 0 0    rgba(214, 51, 132, 0); }
198	}
199	
200	.te-panel {
201	  position: fixed;
202	  z-index: 1998;
203	  right: 24px;
204	  top: 132px;
205	  width: min(360px, calc(100vw - 32px));
206	  padding: 18px 18px 16px;
207	  background: var(--bg);
208	  color: var(--fg);
209	  border: 1px solid var(--border-strong);
210	  border-radius: 16px;
211	  box-shadow: 0 22px 50px rgba(0,0,0,.22), 0 6px 14px rgba(0,0,0,.08);
212	  font-family: var(--font-body);
213	  animation: te-slide-in .2s ease-out;
214	}
215	@keyframes te-slide-in {
216	  from { opacity: 0; transform: translateY(-8px); }
217	  to   { opacity: 1; transform: translateY(0); }
218	}
219	.te-panel-head {
220	  display: flex;
221	  align-items: center;
222	  justify-content: space-between;
223	  gap: 12px;
224	  margin-bottom: 10px;
225	}
226	.te-panel-title {
227	  display: inline-flex;
228	  align-items: center;
229	  gap: 10px;
230	  font-family: var(--font-display);
231	  font-weight: 600;
232	  font-size: .92rem;
233	}
234	.te-panel-close {
235	  background: transparent;
236	  border: none;
237	  color: var(--fg-muted);
238	  width: 28px;
239	  height: 28px;
240	  border-radius: 50%;
241	  display: inline-flex;
242	  align-items: center;
243	  justify-content: center;
244	  cursor: pointer;
245	  font-size: 16px;
246	}
247	.te-panel-close:hover { color: var(--fg); background: var(--bg-subtle); }
248	.te-panel-desc {
249	  font-size: .92rem;
250	  line-height: 1.5;
251	  color: var(--fg-muted);
252	  margin: 0 0 14px;
253	}
254	.te-panel-desc strong { color: var(--fg); }
255	.te-panel-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
256	.te-panel-actions .btn-primary,
257	.te-panel-actions .btn-secondary {
258	  padding: 10px 16px;
259	  font-size: .85rem;
260	}
261	.te-panel-cheats {
262	  font-size: .88rem;
263	  color: var(--fg-muted);
264	  border-top: 1px solid var(--border);
265	  padding-top: 12px;
266	}
267	.te-panel-cheats summary {
268	  font-family: var(--font-display);
269	  font-weight: 600;
270	  color: var(--fg);
271	  cursor: pointer;
272	  list-style: none;
273	  padding: 2px 0;
274	}
275	.te-panel-cheats summary::-webkit-details-marker { display: none; }
276	.te-panel-cheats summary::before {
277	  content: '▸';
278	  display: inline-block;
279	  margin-right: 6px;
280	  transition: transform .15s;
281	  color: var(--brand);
282	}
283	.te-panel-cheats[open] summary::before { transform: rotate(90deg); }
284	.te-panel-cheats ul {
285	  margin: 10px 0 0;
286	  padding: 0 0 0 18px;
287	  display: grid;
288	  gap: 6px;
289	  line-height: 1.5;
290	}
291	.te-panel-cheats em { color: var(--fg); font-style: italic; }
292	.te-error-msg {
293	  margin-top: 10px;
294	  padding: 10px 12px;
295	  background: #fff1f0;
296	  border: 1px solid #ffccc7;
297	  border-radius: 10px;
298	  font-size: .83rem;
299	  color: #cf1322;
300	  line-height: 1.45;
301	}
302	[data-theme="dark"] .te-error-msg {
303	  background: #2a1215;
304	  border-color: #58181c;
305	  color: #ff7875;
306	}
307	
308	/* Press-to-talk button — held to skip the wake word. Active state pulses
309	   the same way the awake dot does so the user sees TE is hearing them. */
310	.te-btn-ptt {
311	  display: inline-flex;
312	  align-items: center;
313	  gap: 6px;
314	  padding: 10px 14px;
315	  font-size: .85rem;
316	  font-family: var(--font-display);
317	  font-weight: 600;
318	  border: 1.5px solid var(--border-strong);
319	  border-radius: 10px;
320	  background: var(--bg);
321	  color: var(--fg);
322	  cursor: pointer;
323	  transition: background .15s, border-color .15s, color .15s, transform .08s;
324	}
325	.te-btn-ptt:hover { border-color: var(--brand); color: var(--brand); }
326	.te-btn-ptt:active,
327	.te-btn-ptt-active {
328	  background: var(--brand);
329	  border-color: var(--brand);
330	  color: #fff;
331	  transform: scale(.98);
332	  box-shadow: 0 0 0 6px rgba(214, 51, 132, .18);
333	}
334	
335	/* FAB while PTT is active — same emphasis as the panel button so the user
336	   sees the FAB respond to long-press. */
337	.te-fab-ptt {
338	  border-color: var(--brand) !important;
339	  background: var(--brand);
340	  color: #fff;
341	  box-shadow: 0 0 0 6px rgba(214, 51, 132, .18), 0 10px 28px rgba(0,0,0,.12);
342	}
343	
344	.te-panel-hint {
345	  margin: 0 0 12px;
346	  font-size: .78rem;
347	  color: var(--fg-muted);
348	  line-height: 1.45;
349	}
350	.te-panel-hint kbd {
351	  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
352	  font-size: .72rem;
353	  padding: 1px 6px;
354	  border: 1px solid var(--border-strong);
355	  border-bottom-width: 2px;
356	  border-radius: 4px;
357	  background: var(--bg-subtle);
358	  color: var(--fg);
359	}
360	
361	.te-last {
362	  margin-top: 14px;
363	  padding: 10px 12px;
364	  background: var(--bg-subtle);
365	  border-radius: 10px;
366	  font-size: .85rem;
367	  color: var(--fg-muted);
368	  line-height: 1.4;
369	}
370	.te-last-lbl {
371	  font-family: var(--font-display);
372	  font-weight: 600;
373	  font-size: .7rem;
374	  letter-spacing: .12em;
375	  text-transform: uppercase;
376	  color: var(--brand);
377	  margin-right: 6px;
378	}
379	
380	[data-theme="dark"] .te-fab,
381	[data-theme="high-contrast"] .te-fab,
382	[data-theme="dark"] .te-panel,
383	[data-theme="high-contrast"] .te-panel {
384	  background: var(--bg);
385	  color: var(--fg);
386	  border-color: var(--border-strong);
387	}
388	
389	@media (max-width: 520px) {
390	  .te-fab { top: auto; bottom: 76px; right: 16px; }
391	  .te-panel { top: auto; bottom: 128px; right: 16px; left: 16px; width: auto; }
392	}
393	@media (prefers-reduced-motion: reduce) {
394	  .te-dot-listen { animation: none; }
395	  .te-panel { animation: none; }
396	}
397	
