1	/* Screen-reader-only text */
2	.sr-only {
3	  position: absolute !important;
4	  width: 1px !important;
5	  height: 1px !important;
6	  padding: 0 !important;
7	  margin: -1px !important;
8	  overflow: hidden !important;
9	  clip: rect(0,0,0,0) !important;
10	  white-space: nowrap !important;
11	  border: 0 !important;
12	}
13	
14	/* Coming-soon page + countdown */
15	.coming-soon {
16	  position: relative;
17	  min-height: calc(100vh - 200px);
18	  display: flex;
19	  align-items: center;
20	  justify-content: center;
21	  padding: clamp(40px, 8vw, 100px) clamp(16px, 6vw, 40px);
22	  overflow: hidden;
23	}
24	.coming-soon .cs-bg {
25	  position: absolute;
26	  inset: 0;
27	  pointer-events: none;
28	  display: grid;
29	  place-items: center;
30	}
31	.coming-soon .cs-ring {
32	  position: absolute;
33	  border-radius: 50%;
34	  border: 1px solid var(--border);
35	  opacity: .55;
36	}
37	.coming-soon .cs-ring-1 { width: 520px; height: 520px; }
38	.coming-soon .cs-ring-2 { width: 760px; height: 760px; border-style: dashed; }
39	.coming-soon .cs-ring-3 { width: 980px; height: 980px; opacity: .3; }
40	
41	.coming-soon .cs-inner {
42	  position: relative;
43	  max-width: 720px;
44	  text-align: center;
45	  z-index: 1;
46	}
47	.coming-soon .cs-eye {
48	  color: var(--brand);
49	  width: 72px;
50	  height: 84px;
51	  margin: 0 auto 20px;
52	}
53	.coming-soon .cs-eye svg { width: 100%; height: 100%; display: block; }
54	.coming-soon .cs-eyebrow { margin-bottom: 10px; }
55	.coming-soon .cs-title {
56	  font-family: var(--font-display);
57	  font-size: clamp(2rem, 5.5vw, 3.25rem);
58	  font-weight: 700;
59	  letter-spacing: -.025em;
60	  line-height: 1.08;
61	  color: var(--fg);
62	  margin: 0 0 18px;
63	}
64	.coming-soon .cs-title em {
65	  font-style: italic;
66	  color: var(--brand);
67	  font-weight: 700;
68	}
69	.coming-soon .cs-sub {
70	  font-size: 1.05rem;
71	  line-height: 1.6;
72	  color: var(--fg-muted);
73	  max-width: 560px;
74	  margin: 0 auto 36px;
75	}
76	.coming-soon .cs-launch-date {
77	  display: inline-flex;
78	  align-items: center;
79	  gap: 8px;
80	  font-size: .9rem;
81	  color: var(--fg-muted);
82	  margin: 22px 0 32px;
83	  padding: 8px 14px;
84	  border: 1px solid var(--border);
85	  border-radius: 999px;
86	  background: var(--bg-subtle);
87	}
88	.coming-soon .cs-launch-date i { color: var(--brand); font-size: 16px; }
89	.coming-soon .cs-actions {
90	  display: flex;
91	  gap: 14px;
92	  justify-content: center;
93	  flex-wrap: wrap;
94	  margin-bottom: 36px;
95	}
96	.coming-soon .cs-footnote {
97	  font-size: .9rem;
98	  color: var(--fg-muted);
99	  padding-top: 28px;
100	  border-top: 1px solid var(--border);
101	  line-height: 1.6;
102	}
103	.coming-soon .cs-footnote a {
104	  color: var(--brand);
105	  text-decoration: none;
106	  border-bottom: 1px solid transparent;
107	  transition: border-color .15s;
108	}
109	.coming-soon .cs-footnote a:hover { border-bottom-color: var(--brand); }
110	
111	.countdown {
112	  display: flex;
113	  align-items: center;
114	  justify-content: center;
115	  gap: clamp(8px, 2vw, 18px);
116	  margin: 12px 0 4px;
117	  font-variant-numeric: tabular-nums;
118	}
119	.countdown-cell {
120	  min-width: clamp(72px, 13vw, 120px);
121	  padding: 18px 12px;
122	  background: var(--bg);
123	  border: 1px solid var(--border-strong);
124	  border-radius: 16px;
125	  box-shadow: 0 6px 22px rgba(0,0,0,.06);
126	  display: grid;
127	  gap: 4px;
128	}
129	.countdown-num {
130	  font-family: var(--font-display);
131	  font-size: clamp(2rem, 5.8vw, 3.25rem);
132	  font-weight: 700;
133	  line-height: 1;
134	  letter-spacing: -.03em;
135	  color: var(--fg);
136	  background: linear-gradient(135deg, var(--brand) 0%, var(--accent, var(--brand)) 100%);
137	  -webkit-background-clip: text;
138	  background-clip: text;
139	  color: transparent;
140	}
141	.countdown-lbl {
142	  font-family: var(--font-display);
143	  font-size: .68rem;
144	  font-weight: 600;
145	  letter-spacing: .14em;
146	  text-transform: uppercase;
147	  color: var(--fg-muted);
148	}
149	.countdown-sep {
150	  font-family: var(--font-display);
151	  font-size: clamp(1.4rem, 3.5vw, 2rem);
152	  font-weight: 700;
153	  color: var(--brand);
154	  opacity: .5;
155	}
156	
157	.countdown-done .countdown-num {
158	  background: none;
159	  -webkit-background-clip: initial;
160	  background-clip: initial;
161	  color: var(--brand);
162	}
163	
164	[data-theme="high-contrast"] .countdown-num {
165	  background: none;
166	  -webkit-background-clip: initial;
167	  background-clip: initial;
168	  color: var(--brand);
169	}
170	
171	@media (max-width: 640px) {
172	  .countdown { gap: 6px; }
173	  .countdown-cell { min-width: 0; padding: 12px 8px; }
174	  .countdown-sep { display: none; }
175	}
176	@media (max-width: 440px) {
177	  .coming-soon .cs-actions { flex-direction: column; align-items: stretch; }
178	  .coming-soon .cs-actions > * { justify-content: center; }
179	  .coming-soon .cs-ring-2, .coming-soon .cs-ring-3 { display: none; }
180	}
181	
182	/* Error pages (404 / 500 / runtime error boundary) */
183	.error-page {
184	  min-height: calc(100vh - 200px);
185	  display: flex;
186	  align-items: center;
187	  justify-content: center;
188	  padding: clamp(40px, 8vw, 120px) clamp(16px, 6vw, 40px);
189	}
190	.error-page .error-inner {
191	  max-width: 640px;
192	  text-align: center;
193	}
194	.error-page .error-code {
195	  font-family: var(--font-display);
196	  font-size: clamp(5.5rem, 18vw, 10rem);
197	  font-weight: 700;
198	  line-height: 1;
199	  letter-spacing: -.04em;
200	  background: linear-gradient(135deg, var(--brand) 0%, var(--accent, var(--brand)) 100%);
201	  -webkit-background-clip: text;
202	  background-clip: text;
203	  color: transparent;
204	  margin-bottom: 12px;
205	}
206	.error-page .error-code-500 {
207	  background: linear-gradient(135deg, #c13a6a 0%, #7b1e50 100%);
208	  -webkit-background-clip: text;
209	  background-clip: text;
210	  color: transparent;
211	}
212	.error-page .section-eyebrow { margin-bottom: 10px; }
213	.error-page .error-title {
214	  font-family: var(--font-display);
