1	import { notFound } from 'next/navigation';
2	import HtmlContent from '@/components/HtmlContent';
3	import { getContent } from '@/lib/cms/db';
4	import { findCustomPage, readCustomPages, renderCustomPage } from '@/lib/pages/custom';
5	import { pageMetadata, readSeoOverrides } from '@/lib/seo';
6	
7	// Reserved slugs that already resolve to concrete routes; must not be shadowed
8	// by a user-defined page slug.
9	const RESERVED = new Set([
10	  'about', 'programs', 'projects', 'donate', 'media', 'documents',
11	  'volunteers', 'blog-detail', 'story-detail', 'coming-soon', 'admin', 'ad-min', 'api',
12	]);
13	
14	// Static export: enumerate every CMS-defined page slug at build time so
15	// Next can prerender each one as its own .html file. Reads from the
16	// new pages.custom shape (CMS-03) and the legacy flat pages array via
17	// readCustomPages. If the backend is unreachable during build OR no
18	// custom pages exist yet, fall back to a single 404 placeholder so
19	// Next can still produce a buildable route.
20	export async function generateStaticParams() {
21	  const content = await getContent();
22	  const pages = readCustomPages(content);
23	  const params = pages
24	    .filter((p) => p && p.slug && p.visible !== false && !RESERVED.has(p.slug))
25	    .map((p) => ({ slug: p.slug }));
26	  if (params.length === 0) return [{ slug: '__placeholder__' }];
27	  return params;
28	}
29	
30	interface SlugRouteProps {
31	  params: Promise<{ slug: string }>;
32	}
33	
34	export async function generateMetadata({ params }: SlugRouteProps) {
35	  const { slug } = await params;
36	  if (RESERVED.has(slug)) return {};
37	  const content = await getContent();
38	  const page = findCustomPage(content, slug);
39	  if (!page) return {};
40	  const o = readSeoOverrides(content, '/' + slug);
41	  return pageMetadata({
42	    title: o.title || (page.title || slug),
43	    description: o.description || page.description || page.excerpt,
44	    path: '/' + slug,
45	    image: o.image || page.image,
46	    noindex: o.noindex,
47	  });
48	}
49	
50	export default async function CustomPage({ params }: SlugRouteProps) {
51	  const { slug } = await params;
52	  if (RESERVED.has(slug)) notFound();
53	  const content = await getContent();
54	  const page = findCustomPage(content, slug);
55	  if (!page) notFound();
56	  return <HtmlContent html={renderCustomPage(page)} />;
57	}
