10	export function readCustomPages(content: SiteContent | null | undefined): CmsCustomPage[] {
11	  const pages = content?.pages;
12	  if (pages && typeof pages === 'object' && !Array.isArray(pages)) {
13	    const custom = (pages as { custom?: unknown }).custom;
14	    return Array.isArray(custom) ? (custom as CmsCustomPage[]) : [];
15	  }
16	  return Array.isArray(pages) ? (pages as CmsCustomPage[]) : [];
17	}
