19	// Find a CMS-defined page by slug. Returns null if missing or hidden.
20	export function findCustomPage(content: SiteContent | null | undefined, slug: string): CmsCustomPage | null {
21	  const pages = readCustomPages(content);
22	  const p = pages.find((x) => x && x.slug === slug);
23	  if (!p) return null;
24	  if (p.visible === false) return null;
25	  return p;
26	}
