38	          ${sec.title ? `<h1>${rich(sec.title)}</h1>` : ''}
39	          ${sec.body ? `<p>${esc(sec.body)}</p>` : ''}
40	        </div>
41	      </div>`;
42	    case 'text':
43	      return `<section class="section">
44	        <div class="section-inner" style="max-width:820px;">
45	          ${sec.heading ? `<div class="section-heading left"><h2 class="section-title">${esc(sec.heading)}</h2></div>` : ''}
46	          <div class="cms-prose" style="font-size:1.02rem;color:var(--fg-muted);line-height:1.75;">
47	            ${esc(sec.body || '').split(/\n\n+/).map((p) => `<p>${esc(p).replace(/\n/g, '<br>')}</p>`).join('')}
48	          </div>
49	        </div>
50	      </section>`;
51	    case 'rich':
52	      // Author-trusted HTML block. The CMS presents this with a warning.
53	      return `<section class="section">
54	        <div class="section-inner" style="max-width:900px;">${rich(sec.html || '')}</div>
55	      </section>`;
56	    case 'cta':
57	      return `<section class="cta-band">
58	        <div class="cta-inner">
59	          ${sec.heading ? `<h2>${esc(sec.heading)}</h2>` : ''}
