61	          <div style="display:flex;gap:14px;flex-wrap:wrap;justify-content:center;">
62	            ${sec.primaryLabel ? `<a class="btn-accent" href="${esc(sec.primaryHref || '#')}">${iconSvg('heart', 'fill')} ${esc(sec.primaryLabel)}</a>` : ''}
63	            ${sec.secondaryLabel ? `<a class="btn-secondary" href="${esc(sec.secondaryHref || '#')}">${esc(sec.secondaryLabel)}</a>` : ''}
64	          </div>
65	        </div>
66	      </section>`;
67	    default:
68	      return '';
69	  }
70	}
