  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(10, 8, 16, .72);
  animation: tour-fade-in .25s ease-out;
}
[data-theme="high-contrast"] .tour-overlay { background: rgba(0, 0, 0, .92); }
@keyframes tour-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.tour-card {
  position: relative;
  width: min(620px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  text-align: center;
  padding: clamp(36px, 6vw, 64px) clamp(28px, 5vw, 56px);
  border-radius: var(--radius-xl);
  background: var(--bg-elevated);
  color: var(--fg);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-lg);
  font-family: var(--font-body, inherit);
  animation: tour-pop-in .35s cubic-bezier(.16, 1, .3, 1);
}
/* Gold hairline across the top of the dialog. */
.tour-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 8%, var(--brand) 50%, transparent 92%);
  pointer-events: none;
}
@keyframes tour-pop-in {
  from { opacity: 0; transform: scale(.95) translateY(10px); }
  to   { opacity: 1; transform: scale(1)   translateY(0); }
}
.tour-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--fg-muted);
  font-size: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background .15s, color .15s;
}
.tour-close:hover { background: var(--bg-subtle); color: var(--fg); }

/* Gold ring motif — the single decorative motif in this viewport.
   Two echo ripples breathe outward from the microphone. */
.tour-icon {
  position: relative;
  width: 76px;
  height: 76px;
  border-radius: 50%;
  background: var(--brand-subtle);
  border: 1px solid var(--brand);
  color: var(--brand);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  margin-bottom: 22px;
}
.tour-icon::before,
.tour-icon::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid var(--brand);
  opacity: 0;
  animation: tour-echo 6s ease-out infinite;
  pointer-events: none;
}
.tour-icon::after { animation-delay: 3s; }
@keyframes tour-echo {
  0%   { transform: scale(1);    opacity: .55; }
  60%  { transform: scale(1.85); opacity: 0; }
  100% { transform: scale(1.85); opacity: 0; }
}
.tour-eyebrow {
  font-family: var(--font-body, inherit);
  font-size: .76rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 12px;
}
.tour-title {
  font-family: var(--font-display, inherit);
  font-size: clamp(1.7rem, 4.4vw, 2.5rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.12;
  margin: 0 0 16px;
  color: var(--fg);
  text-wrap: balance;
}
.tour-title em { font-style: italic; color: var(--brand); }
.tour-desc {
  font-size: 1.02rem;
  line-height: 1.65;
  color: var(--fg-muted);
  max-width: 48ch;
  margin: 0 auto 20px;
}
.tour-desc strong { color: var(--fg); font-weight: 700; }
.tour-countdown {
  display: inline-block;
  font-size: .9rem;
  color: var(--fg-muted);
  margin-bottom: 22px;
  padding: 8px 16px;
  border-radius: var(--radius-full);
  background: var(--bg-subtle);
  border: 1px solid var(--border);
}
.tour-countdown strong { color: var(--brand); font-weight: 700; font-variant-numeric: tabular-nums; }
.tour-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}
.tour-btn {
  font-family: var(--font-body, inherit);
  font-size: .95rem;
  font-weight: 700;
  min-height: 48px;
  padding: 12px 26px;
  border-radius: var(--radius-full);
  border: 1.5px solid transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background .15s, color .15s, border-color .15s, transform .1s;
}
.tour-btn:active { transform: scale(.97); }
.tour-btn-primary {
  background: var(--brand);
  color: var(--brand-fg);
}
.tour-btn-primary:hover { background: var(--brand-hover); color: var(--brand-fg); }
.tour-btn-ghost {
  background: transparent;
  color: var(--brand);
  border-color: var(--brand);
}
.tour-btn-ghost:hover { background: var(--brand-subtle); color: var(--brand-hover); border-color: var(--brand-hover); }

@media (max-width: 520px) {
  .tour-overlay { padding: 12px; }
  .tour-card    { padding: 32px 24px; border-radius: var(--radius-lg); }
  .tour-actions { flex-direction: column; align-items: stretch; }
  .tour-btn     { justify-content: center; }
}
@media (prefers-reduced-motion: reduce) {
  .tour-overlay, .tour-card { animation: none; }
  .tour-icon::before, .tour-icon::after { animation: none; opacity: 0; }
}

/* ── TE — voice assistant floating button + panel ─────────────────
   All ids (#te-panel), state classes (te-status-*, te-dot-*,
   te-fab-ptt, te-btn-ptt-active) are contracts with VoiceAssistant.tsx
   and its tests. Night surface, gold live/listening states. */
.te-fab {
  position: fixed;
  z-index: 1998;
  right: 24px;
  top: 88px; /* below the fixed topnav */
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 9px 16px 9px 12px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-strong);
  background: var(--bg-elevated);
  color: var(--fg);
  font-family: var(--font-body);
  font-weight: 700;
  letter-spacing: .08em;
  font-size: .78rem;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: border-color .15s, background .15s, color .15s, transform .1s;
}
.te-fab:hover { border-color: var(--brand); color: var(--brand); }
.te-fab:active { transform: scale(.97); }
.te-fab-label { letter-spacing: .14em; }

.te-fab.te-status-awake  { border-color: var(--brand); color: var(--brand); }
.te-fab.te-status-listening { border-color: var(--brand); }

.te-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--fg-muted);
  flex: 0 0 auto;
  display: inline-block;
}
.te-dot-off    { background: var(--border-strong); }
.te-dot-listen { background: var(--brand); box-shadow: 0 0 0 0 var(--brand-subtle); animation: te-pulse 1.6s infinite; }
.te-dot-awake  { background: var(--brand); box-shadow: 0 0 0 6px var(--brand-subtle); }
@keyframes te-pulse {
  0%   { box-shadow: 0 0 0 0    var(--brand-subtle); }
  70%  { box-shadow: 0 0 0 10px transparent; }
  100% { box-shadow: 0 0 0 0    transparent; }
}

.te-panel {
  position: fixed;
  z-index: 1998;
  right: 24px;
  top: 140px;
  width: min(360px, calc(100vw - 32px));
  padding: 18px 18px 16px;
  background: var(--bg-elevated);
  color: var(--fg);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  font-family: var(--font-body);
  animation: te-slide-in .2s ease-out;
  overflow: hidden;
}
/* Gold hairline across the top of the panel. */
.te-panel::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 8%, var(--brand) 50%, transparent 92%);
  pointer-events: none;
}
@keyframes te-slide-in {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}
.te-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.te-panel-title {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: .95rem;
}
.te-panel-close {
  background: transparent;
  border: none;
  color: var(--fg-muted);
  width: 44px;
  height: 44px;
  margin: -8px -10px -8px 0;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 16px;
  transition: background .15s, color .15s;
}
.te-panel-close:hover { color: var(--fg); background: var(--bg-subtle); }
.te-panel-desc {
  font-size: .92rem;
  line-height: 1.55;
  color: var(--fg-muted);
  margin: 0 0 14px;
}
.te-panel-desc strong { color: var(--fg); }
.te-panel-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.te-panel-actions .btn-primary,
.te-panel-actions .btn-secondary {
  min-height: 44px;
  padding: 10px 18px;
  font-size: .85rem;
}
.te-panel-cheats {
  font-size: .88rem;
  color: var(--fg-muted);
  border-top: 1px solid var(--border);
  padding-top: 12px;
}
.te-panel-cheats summary {
  font-family: var(--font-display);
  font-weight: 600;
  color: var(--fg);
  cursor: pointer;
  list-style: none;
  padding: 8px 0;
}
.te-panel-cheats summary::-webkit-details-marker { display: none; }
.te-panel-cheats summary::before {
  content: '▸';
  display: inline-block;
  margin-right: 6px;
  transition: transform .15s;
  color: var(--brand);
}
.te-panel-cheats[open] summary::before { transform: rotate(90deg); }
.te-panel-cheats ul {
  margin: 10px 0 0;
  padding: 0 0 0 18px;
  display: grid;
  gap: 6px;
  line-height: 1.5;
}
.te-panel-cheats em { color: var(--fg); font-style: italic; }

/* Error message — semantic red, tuned per theme (no error token exists).
   The role="alert" + text carries the state; color is reinforcement. */
.te-error-msg {
  margin-top: 10px;
  padding: 10px 12px;
  background: #fdecea;
  border: 1px solid #f0b3ab;
  border-radius: var(--radius-md);
  font-size: .83rem;
  color: #a4262c;
  line-height: 1.45;
}
[data-theme="dark"] .te-error-msg {
  background: #2a1518;
  border-color: #5c2a30;
  color: #ff9d95;
}
[data-theme="high-contrast"] .te-error-msg {
  background: #000;
  border: 2px solid #fff;
  color: #fff;
}

/* Press-to-talk button — held to skip the wake word. Active state pulses
   the same way the awake dot does so the user sees TE is hearing them. */
.te-btn-ptt {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 10px 16px;
  font-size: .85rem;
  font-family: var(--font-body);
  font-weight: 700;
  border: 1.5px solid var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  color: var(--fg);
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s, transform .08s;
}
.te-btn-ptt:hover { border-color: var(--brand); color: var(--brand); }
.te-btn-ptt:active,
.te-btn-ptt-active {
  background: var(--brand);
  border-color: var(--brand);
  color: var(--brand-fg);
  transform: scale(.98);
  box-shadow: 0 0 0 6px var(--brand-subtle);
}

/* FAB while PTT is active — same emphasis as the panel button so the user
   sees the FAB respond to long-press. */
.te-fab-ptt {
  border-color: var(--brand) !important;
  background: var(--brand);
  color: var(--brand-fg);
  box-shadow: 0 0 0 6px var(--brand-subtle), var(--shadow-md);
}

.te-panel-hint {
  margin: 0 0 12px;
  font-size: .78rem;
  color: var(--fg-muted);
  line-height: 1.45;
}
.te-panel-hint kbd {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
  font-size: .72rem;
  padding: 1px 6px;
  border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--bg-subtle);
  color: var(--fg);
}

.te-last {
  margin-top: 14px;
  padding: 10px 12px;
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: .85rem;
  color: var(--fg-muted);
  line-height: 1.4;
}
.te-last-lbl {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: .7rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--brand);
  margin-right: 6px;
}

@media (max-width: 520px) {
  .te-fab { top: auto; bottom: 76px; right: 16px; }
  .te-panel { top: auto; bottom: 128px; right: 16px; left: 16px; width: auto; }
}
@media (prefers-reduced-motion: reduce) {
  .te-dot-listen { animation: none; }
  .te-panel { animation: none; }
}

/* Audio tour mini-player (shown while tour is playing/paused).
   Night surface, gold controls — all class hooks are contracts with
   AudioTour.tsx. */
.audio-tour-player {
  position: fixed;
  z-index: 1999;
  left: 24px;
  bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px 10px 10px;
  max-width: 420px;
  background: var(--bg-elevated);
  color: var(--fg);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-lg);
  font-family: var(--font-body, inherit);
  animation: atp-slide-in .25s ease-out;
}
@keyframes atp-slide-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
.audio-tour-player .atp-btn {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, color .15s;
}
.audio-tour-player .atp-toggle {
  background: var(--brand);
  color: var(--brand-fg);
  font-size: 20px;
}
.audio-tour-player .atp-toggle:hover { background: var(--brand-hover); color: var(--brand-fg); }
.audio-tour-player .atp-close {
  background: transparent;
  color: var(--fg-muted);
  font-size: 18px;
}
.audio-tour-player .atp-close:hover { color: var(--fg); background: var(--bg-subtle); }
.audio-tour-player .atp-info {
  min-width: 160px;
  flex: 1 1 auto;
  display: grid;
  gap: 4px;
}
.audio-tour-player .atp-label {
  font-family: var(--font-display, inherit);
  font-size: .84rem;
  font-weight: 600;
  letter-spacing: -.01em;
}
.audio-tour-player .atp-progress-wrap {
  height: 4px;
  border-radius: 2px;
  background: var(--border);
  overflow: hidden;
}
.audio-tour-player .atp-progress-bar {
  height: 100%;
  background: var(--brand);
  transition: width .25s linear;
}
.audio-tour-player .atp-time {
  display: flex;
  gap: 4px;
  font-size: .72rem;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 520px) {
  .audio-tour-player {
    left: 12px;
    right: 12px;
    bottom: 12px;
    max-width: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .audio-tour-player { animation: none; }
  .audio-tour-player .atp-progress-bar { transition: none; }
}

/* Screen-reader-only text */
.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0,0,0,0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* ── Coming-soon page + countdown ─────────────────────────────────
   Night statement page. The echo-ripple ring field is the single
   decorative motif in the viewport (aria-hidden in the markup). */
.coming-soon {
  position: relative;
  min-height: calc(100vh - 200px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(40px, 8vw, 100px) clamp(16px, 6vw, 40px);
  overflow: hidden;
}
.coming-soon .cs-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: grid;
  place-items: center;
  animation: cs-breathe 6s ease-in-out infinite alternate;
}
@keyframes cs-breathe {
  from { transform: scale(1); }
  to   { transform: scale(1.04); }
}
.coming-soon .cs-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--brand);
  opacity: .22;
}
.coming-soon .cs-ring-1 { width: 520px; height: 520px; }
.coming-soon .cs-ring-2 { width: 760px; height: 760px; border-color: var(--border-strong); opacity: .5; }
.coming-soon .cs-ring-3 { width: 980px; height: 980px; border-color: var(--border); opacity: .45; }

.coming-soon .cs-inner {
  position: relative;
  max-width: 720px;
  text-align: center;
  z-index: 1;
}
.coming-soon .cs-eye {
  color: var(--brand);
  width: 64px;
  height: 75px;
  margin: 0 auto 24px;
}
.coming-soon .cs-eye svg { width: 100%; height: 100%; display: block; }
.coming-soon .cs-eyebrow { margin-bottom: 10px; }
.coming-soon .cs-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5.5vw, 3.25rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.08;
  color: var(--fg);
  margin: 0 0 18px;
  text-wrap: balance;
}
.coming-soon .cs-title em {
  font-style: italic;
  color: var(--brand);
}
.coming-soon .cs-sub {
  font-size: 1.05rem;
  line-height: 1.65;
  color: var(--fg-muted);
  max-width: 560px;
  margin: 0 auto 36px;
}
.coming-soon .cs-launch-date {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  font-size: .9rem;
  color: var(--fg-muted);
  margin: 22px 0 32px;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--bg-subtle);
}
.coming-soon .cs-launch-date i { color: var(--brand); font-size: 16px; }
.coming-soon .cs-actions {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 36px;
}
.coming-soon .cs-footnote {
  font-size: .9rem;
  color: var(--fg-muted);
  padding-top: 28px;
  border-top: 1px solid var(--border);
  line-height: 1.6;
}
.coming-soon .cs-footnote a {
  color: var(--brand);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: var(--brand-subtle);
  transition: text-decoration-color .15s;
}
.coming-soon .cs-footnote a:hover { text-decoration-color: var(--brand); color: var(--brand-hover); }

/* Countdown — oversized Literata numerals in gold on elevated night
   cards, each capped with a gold hairline. */
.countdown {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 2vw, 18px);
  margin: 12px 0 4px;
  font-variant-numeric: tabular-nums;
}
.countdown-cell {
  min-width: clamp(72px, 13vw, 120px);
  padding: 18px 12px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: inset 0 1px 0 var(--brand);
  display: grid;
  gap: 6px;
}
.countdown-num {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5.8vw, 3.25rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
  color: var(--brand);
}
.countdown-lbl {
  font-family: var(--font-body);
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--fg-muted);
}
.countdown-sep {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 3.5vw, 2rem);
  font-weight: 600;
  color: var(--fg-subtle);
}
.countdown-done .countdown-num { color: var(--fg); }

@media (max-width: 640px) {
  .countdown { gap: 6px; }
  .countdown-cell { min-width: 0; padding: 12px 8px; }
  .countdown-sep { display: none; }
}
@media (max-width: 440px) {
  .coming-soon .cs-actions { flex-direction: column; align-items: stretch; }
  .coming-soon .cs-actions > * { justify-content: center; }
  .coming-soon .cs-ring-2, .coming-soon .cs-ring-3 { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .coming-soon .cs-bg { animation: none; }
}

/* ── Error pages (404 / 500 / runtime error boundary) ─────────────
   Night + one ripple motif (CSS-only rings behind the numeral) +
   an oversized Literata statement. */
.error-page {
  position: relative;
  min-height: calc(100vh - 200px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(40px, 8vw, 120px) clamp(16px, 6vw, 40px);
  overflow: hidden;
}
.error-page::before,
.error-page::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid var(--brand);
  opacity: .18;
  pointer-events: none;
}
.error-page::before { width: 560px; height: 560px; }
.error-page::after  { width: 860px; height: 860px; border-color: var(--border-strong); opacity: .5; }

.error-page .error-inner {
  position: relative;
  z-index: 1;
  max-width: 640px;
  text-align: center;
}
.error-page .error-code {
  font-family: var(--font-display);
  font-size: clamp(5.5rem, 18vw, 10rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -.04em;
  font-variant-numeric: tabular-nums;
  color: var(--brand);
  margin-bottom: 12px;
}
.error-page .section-eyebrow { margin-bottom: 10px; }
.error-page .error-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.1;
  color: var(--fg);
  margin: 0 0 20px;
  text-wrap: balance;
}
.error-page .error-title em {
  font-style: italic;
  color: var(--brand);
}
.error-page .error-sub {
  font-size: 1.05rem;
  line-height: 1.65;
  color: var(--fg-muted);
  max-width: 520px;
  margin: 0 auto 32px;
}
.error-page .error-digest {
  font-size: .85rem;
  color: var(--fg-muted);
  margin: -16px 0 28px;
}
.error-page .error-digest code {
  font-family: var(--font-mono, ui-monospace, monospace);
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: .82rem;
  color: var(--fg);
}
.error-page .error-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 48px;
}
.error-page .error-links {
  text-align: left;
  max-width: 440px;
  margin: 0 auto;
  padding-top: 32px;
  border-top: 1px solid var(--border);
}
.error-page .error-links-title {
  font-family: var(--font-body);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 10px;
}
.error-page .error-links ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 2px;
}
.error-page .error-links a {
  color: var(--fg);
  font-size: .95rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 4px 0;
  border-bottom: 1px solid transparent;
  transition: color .15s, border-color .15s;
}
.error-page .error-links a:hover {
  color: var(--brand);
  border-bottom-color: var(--brand);
}

@media (max-width: 520px) {
  .error-page .error-actions { flex-direction: column; align-items: stretch; }
  .error-page .error-actions > * { justify-content: center; }
  .error-page::after { display: none; }
}

/* ── Confirmed page (double-opt-in landing) ───────────────────────
   Same night-statement family as the error pages: centered Literata
   statement over a single quiet ring. */
.confirmed-page {
  position: relative;
  min-height: calc(100vh - 300px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(48px, 8vw, 120px) clamp(16px, 6vw, 40px);
  overflow: hidden;
}
.confirmed-page::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 620px;
  height: 620px;
  border-radius: 50%;
  border: 1px solid var(--brand);
  opacity: .18;
  pointer-events: none;
}
.confirmed-inner {
  position: relative;
  z-index: 1;
  max-width: 620px;
  text-align: center;
}
.confirmed-inner .section-heading { margin-bottom: 32px; }
.confirmed-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}
@media (max-width: 440px) {
  .confirmed-actions { flex-direction: column; align-items: stretch; }
  .confirmed-actions > * { justify-content: center; }
}

/* ── Legal / privacy page ─────────────────────────────────────────
   Left-aligned editorial head with a gold hairline, then .prose. */
.legal-inner { max-width: 760px; }
.legal-head {
  text-align: left;
  margin-bottom: 36px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--brand);
}
.legal-head .section-subtitle { margin: 0; font-size: .95rem; }

/* ── Detail pages (lib/pages server HTML) ─────────────────────────
   The builders in lib/pages/*.ts ship their own <style> blocks which
   still carry the pre-redesign palette (old blue avatar gradients,
   orange story tags, violet drop caps). The builders are read-only,
   and their inline <style> comes later in document order — so these
   overrides use strictly higher specificity to win the cascade. */

/* Avatars: gold monogram discs, night text on gold (never light-on-gold). */
.article .article-byline-avatar,
div.article-author-bio .bio-avatar,
.fs .fs-byline-avatar,
.story .story-hero-reporter .sh-avatar,
.story .story-credit-col li .av {
  background: var(--brand);
  color: var(--brand-fg);
}

/* Story hero sits on a fixed dark photograph in every theme, so the
   tag tint uses literal saffron (theme tokens would flip to dark gold
   on Day and vanish against the photo — same reasoning as the
   builder's hard-coded whites there). */
.story .story-hero-tag {
  background: rgba(232, 163, 61, .16);
  border-color: rgba(232, 163, 61, .45);
}
.story .story-hero-tag .dot {
  background: #e8a33d;
  box-shadow: 0 0 0 4px rgba(232, 163, 61, .25);
}

/* House style: <em> in display titles = Literata italic gold.
   On the photo hero the light gold hover tone keeps AA against the
   darkened image; elsewhere the token does the theme work. */
.story .story-hero-title em { font-style: italic; color: #f2b856; }
.story .story-hero-title em::after { display: none; }
.story .story-h2 em { font-style: italic; color: var(--brand); }
.article .article-title em { font-style: italic; color: var(--brand); }

/* Drop cap + section dingbats go gold. */
.story .story-body p:first-of-type::first-letter { color: var(--brand); }
.story .story-end { color: var(--brand); }

/* Aside card: old blue tint → flat night card with gold hairline edge. */
.story .story-aside {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-left: 3px solid var(--brand);
}
[data-theme="dark"] .story .story-aside,
[data-theme="high-contrast"] .story .story-aside {
  background: var(--bg-elevated);
  border-color: var(--border);
  border-left-color: var(--brand);
}

/* Research figure frames: old blue stripe fill → quiet night duotone. */
.article .figure-frame {
  background: linear-gradient(135deg, var(--brand-subtle) 0%, var(--accent-subtle) 100%);
}

